mapper.select:
SELECT 
FROM hm_emotion_stats
WHERE stat_period = #{statPeriod}
  AND stat_date = #{statDate}
  AND emotion = #{emotion}
LIMIT 1

SELECT 
FROM hm_emotion_stats
WHERE stat_period = #{statPeriod}
  AND stat_date >= #{startDate}
  AND stat_date <= #{endDate}
ORDER BY stat_date ASC

mapper.delete:
DELETE FROM hm_emotion_stats
WHERE stat_period = #{statPeriod}
  AND stat_date = #{statDate}
